let font;

function myBezierPoint(p0, p1, p2, p3, t) {
  const u = 1 - t;
  return (
    u * u * u * p0 + 3 * u * u * t * p1 + 3 * u * t * t * p2 + t * t * t * p3
  );
}

function myBezierTangent(p0, p1, p2, p3, t) {
  const u = 1 - t;
  const dx =
    3 * u * u * (p1 - p0) + 6 * u * t * (p2 - p1) + 3 * t * t * (p3 - p2);
  return dx;
}

function myBezierPath(start, end, a1, a2, L1 = 100, L2 = 100, steps = 100) {
  const points = [];
  const { x: x0, y: y0 } = start;
  const { x: x3, y: y3 } = end;

  const x1 = x0 + L1 * Math.cos(a1);
  const y1 = y0 + L1 * Math.sin(a1);
  const x2 = x3 - L2 * Math.cos(a2);
  const y2 = y3 - L2 * Math.sin(a2);

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = myBezierPoint(x0, x1, x2, x3, t);
    const y = myBezierPoint(y0, y1, y2, y3, t);
    const dx = myBezierTangent(x0, x1, x2, x3, t);
    const dy = myBezierTangent(y0, y1, y2, y3, t);
    const a = Math.atan2(dy, dx);
    points.push({ x, y, a });
  }

  return points;
}

