    textSize(ts2);
    textFont(font2);
    text(haiku2[i], tx2, ty2 + (i * ts2))
  }


  // Get the point array.

  text1Complete = 0;
  text2Complete = 0;

  for (const pt of points) {
    if (pt.startTime == undefined)
      pt.startTime = floor(frameCount + pt.x1 / 10 + 30 * noise(pt.y1));
    if (pt.endTime == undefined) pt.endTime = pt.startTime + random(100, 130);

    if (!reverseAnim)
      ii = floor(
        map(
          frameCount,
          pt.startTime,
          pt.endTime,
          0,
          pt.curvePath.length - 1,
          true
        )
      );
    else
      ii = floor(
        map(
          frameCount,
          pt.startTime,
          pt.endTime,
          pt.curvePath.length - 1,
          0,
          true
        )
      );

    if(ii==0) text1Complete++
    if(ii==pt.curvePath.length - 1) text2Complete++

    pt.x = pt.curvePath[ii].x;
    pt.y = pt.curvePath[ii].y;
    pt.a = pt.curvePath[ii].a;

    let l = floor(width/20);

    push();
    translate(pt.x, pt.y);
    rotate(pt.a);
    strokeWeight(0.5);
    stroke(100, 0, 0, 10);
    line(-l, 0, l, 0);
    strokeWeight(width/800);
    stroke(100, 0, 0, 250);
    line(-1, 0, 1, 0);
    pop();
  }

  text1Complete=floor(text1Complete/points.length * 100)
  text2Complete=floor(text2Complete/points.length * 100)

  if (playSound && frameCount % 150 == 0) {
    i = floor(random(0,3))
    console.log("Bell " + i);
    bell[i].amp(random(0.01,0.1));
    bell[i].play();
  }

  if (playSound && frameCount % (30*3) == 0) {
    i = floor(random(0,3))
    console.log("Bird " + i);
    bird[i].play();
  }

  if (frameCount > 0 && frameCount % 300 == 0) {
    reverseAnim = !reverseAnim;
    for (const pt of points) {
      {
        pt.startTime = undefined;
        pt.endTime = undefined;
      }
    }
  }

  describe(
    "A Basho Haiku 'Spring Departure' - translates from Japannese to English in flowing particles on a floral background. Click for sound."
  );
}

